+      op && threadSegmentSize == 1 && bases[kReg].size() <= 2 &&
+      llvm::none_of(bases[kReg], inSegment) && numSegments <= 64 &&
+      llvm::none_of(bases[kLane], [](const auto &basis) {
+        return llvm::all_of(basis, [](int32_t x) { return x == 0; });
